command:
cat > /root/certrotate/templates/nginx-cert-rotation.conf.j2 <<'ANTRIEB_EOF'
server {
    listen {{ https_port }} ssl;
    server_name {{ cert_common_name }};

    ssl_certificate     /etc/nginx/ssl/live/cert.pem;
    ssl_certificate_key /etc/nginx/ssl/live/key.pem;

    location / {
        default_type text/plain;
        return 200 "ok\n";
    }
}
ANTRIEB_EOF
cat > /root/certrotate/templates/cert-renew.service.j2 <<'ANTRIEB_EOF'
[Unit]
Description=Renew self-signed TLS certificate for nginx on port {{ https_port }}
After=network.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/renew-selfsigned-cert.sh
ANTRIEB_EOF
cat > /root/certrotate/templates/cert-renew.timer.j2 <<'ANTRIEB_EOF'
[Unit]
Description=Periodically check and renew nginx TLS certificate before expiry

[Timer]
OnBootSec=2min
OnUnitActiveSec={{ cert_renew_check_interval }}
AccuracySec=30s
Persistent=true

[Install]
WantedBy=timers.target
ANTRIEB_EOF
